module top (clk,rst,key,led);
input clk;
input rst;
input key;
output reg led;
wire key_pulse;
当按键按下时产生一个高脉冲，翻转一次
// led
always @(posedge clk or negedge rst)
begin
if (!rst)
led <= 1'b1;
else if (key_pulse)
led <= ~led;
else
led <= led;
end
